from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 280, "תרשים א: האנרגיה הקינטית של התיבה כפונקציה של המקום: 16 ג'אול קבועה עד 20 מטר, ואחר כך עולה בקו ישר ל-40 ג'אול ב-50 מטר. תרשים ב: אנרגיית הגובה כפונקציה של האנרגיה הקינטית: קו ישר מ-10 ג'אול ל-0")
    X, Y = g.graph(60, 220, 210, 170, "x (m)", "Ek (J)", xticks=[(20, "20"), (50, "50")], yticks=[(16, "16"), (40, "40")], xmax=60, ymax=45, grid=False)
    g.plot(X, Y, [(0, 16), (20, 16), (50, 40)]); g.guide(X, Y, 50, 40); g.line(X(20), Y(16), X(20), Y(0), stroke="var(--d-dim)", width=1, dash="4 3")
    g.heb(160, 274, "תרשים א")
    X, Y = g.graph(340, 220, 180, 170, "Ek (J)", "Ep (J)", xticks=[(v, str(v)) for v in (2, 4, 6, 8, 10, 12)], yticks=[(v, str(v)) for v in (2, 4, 6, 8, 10, 12)], xmax=12, ymax=12)
    g.plot(X, Y, [(0, 10), (10, 0)])
    for i in range(11): g.dot(X(i), Y(10 - i), 2.5)
    g.heb(430, 274, "תרשים ב")
    return g

E(id="bagrut-2009-q4", year=2009, label="2009 שאלה 4", topic="energy", sub="en-friction", diff=3, fig=fig,
  stem=r"תיבה שמסתה $0.5\,\text{kg}$ נעה בקו ישר על משטח אופקי מחוספס, בכיוון החיובי של ציר $x$. מקדם החיכוך הקינטי בין התיבה למשטח $\mu_k = 0.1$. ברגע $t = 0$ התיבה בנקודה $x = 0$. הגרף בתרשים א מראה את האנרגיה הקינטית $E_k$ של התיבה כפונקציה של המקום $x$, ב-$50$ המטרים הראשונים של התנועה.",
  parts=[
    P("א", r"האם בעשרים המטרים הראשונים פועל על התיבה כוח אופקי נוסף על החיכוך? הסבירו.", choice(["כן", "לא"], 0), ["graph", "principle"], [
        S(r"האנרגיה הקינטית קבועה", r"לפי משפט העבודה והאנרגיה, העבודה הכוללת אפס. החיכוך עושה עבודה שלילית, ולכן חייב לפעול כוח נוסף שעושה עבודה חיובית ומאזן אותו", r"W_{\text{tot}} = \Delta E_k = 16 - 16 = 0", eq=r"W_{\text{tot}} = \Delta E_k"),
    ], r"כן: האנרגיה הקינטית לא קטנה, למרות החיכוך", key=r"כן"),
    P("ב", r"מ-$x = 20\,\text{m}$ עד $x = 50\,\text{m}$ פועל על התיבה, נוסף על החיכוך, כוח אופקי קבוע $F_1$. מה גודל הכוח $F_1$?", num(1.3, "N"), ["graph", "principle"], [
        D(r"תרשים הכוחות על התיבה", lambda: fbd([("F₁", 0, 0.65), ("fₖ", 180, 0.3), ("N", 90, 1.0), ("mg", -90, 1.0)],
            "תרשים כוחות על התיבה: הכוח אף אחת בכיוון התנועה, חיכוך קינטי נגד התנועה, הכוח הנורמלי כלפי מעלה וכוח הכובד כלפי מטה. הכיוון החיובי הוא כיוון התנועה",
            positive=0, body="block", surface="below")),
        S(r"משפט העבודה והאנרגיה", r"העבודה של כל כוח היא הכוח כפול הדרך. הכוח הנוסף בכיוון התנועה, והחיכוך נגדה. הכוח הנורמלי והכובד ניצבים לתנועה ולא עושים עבודה", r"F_1 \cdot 30 - f_k \cdot 30 = 40 - 16", eq=r"W_{\text{tot}} = \Delta E_k"),
        S(r"מציבים את החיכוך", r"הכוח הנורמלי שווה לכובד", r"f_k = \mu N = 0.1 \cdot 0.5 \cdot 10 = 0.5\,\text{N}", eq=r"f_k = \mu_k N"),
        S(r"פותרים", r"מחלקים בדרך", r"F_1 - 0.5 = \frac{24}{30} = 0.8 \;\Rightarrow\; F_1 = 1.3\,\text{N}"),
    ], r"$1.3\,\text{N}$", key=r"F1=1.3 N"),
    P("ג", r"ברגע שהתיבה מגיעה ל-$x = 50\,\text{m}$ הכוח $F_1$ מפסיק לפעול. מה העבודה של כוח החיכוך מ-$x = 0$ עד שהתיבה נעצרת?", num(-65, "J"), ["principle", "signs"], [
        S(r"הדרך אחרי חמישים מטר", r"נשאר רק החיכוך, והוא לוקח את כל האנרגיה הקינטית", r"-f_k\,d = 0 - 40 \;\Rightarrow\; 0.5\,d = 40 \;\Rightarrow\; d = 80\,\text{m}", eq=r"W_{\text{tot}} = \Delta E_k"),
        S(r"העבודה של החיכוך", r"החיכוך פועל לאורך כל הדרך, מאה ושלושים מטר, תמיד נגד התנועה", r"W_{f} = f_k \cos 180^\circ \cdot 130 = -0.5 \cdot 130 = -65\,\text{J}", eq=r"W = F\cos\theta\,\Delta s"),
    ], r"$-65\,\text{J}$", key=r"Wf=−65 J"),
    P("ד", r"נניח שמ-$x = 20\,\text{m}$ עד $x = 50\,\text{m}$ מפעילים על התיבה, במקום $F_1$, כוח $F_2$ שנטוי בזווית $\alpha$ מעל האופק, והרכיב האופקי שלו שווה ל-$F_1$. האם האנרגיה הקינטית ב-$x = 50\,\text{m}$ תהיה שווה ל-$40\,\text{J}$, גדולה ממנה או קטנה ממנה? הסבירו.", choice(["שווה", "גדולה", "קטנה"], 1), ["fbd", "principle"], [
        D(r"תרשים הכוחות על התיבה עם הכוח הנטוי", lambda: fbd([("F₂", 30, 0.75), ("fₖ", 180, 0.25), ("N", 90, 0.8), ("mg", -90, 1.0)],
            "תרשים כוחות על התיבה: הכוח אף שתיים נטוי מעל האופק, חיכוך קינטי נגד התנועה, הכוח הנורמלי כלפי מעלה, קטן יותר מכוח הכובד, וכוח הכובד כלפי מטה",
            positive=0, body="block", surface="below")),
        S(r"משוואת כוחות בניצב למשטח", r"אין תנועה בכיוון הזה. הרכיב האנכי של הכוח מרים מעט את התיבה, ולכן הכוח הנורמלי קטן", r"N + F_2\sin\alpha - mg = 0 \;\Rightarrow\; N = mg - F_2\sin\alpha < mg", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מסקנה", r"החיכוך פרופורציוני לכוח הנורמלי, ולכן הוא קטן. העבודה של הרכיב האופקי זהה, והחיכוך לוקח פחות", r"f_k = \mu N < 0.5\,\text{N} \;\Rightarrow\; E_k > 40\,\text{J}", eq=r"f_k = \mu_k N"),
    ], r"גדולה: החיכוך קטן יותר", key=r"גדולה מ-40 J"),
    P("ה", r"גוף קטן נע על משטח כלשהו. הגרף בתרשים ב מראה את הקשר בין אנרגיית הגובה של הגוף לאנרגיה הקינטית שלו. איזה מההיגדים מתאים לגרף? (1) הגוף נע על משטח אופקי חלק, בהשפעת כוח קבוע. (2) הגוף נע במורד מישור משופע מחוספס. (3) הגוף נופל נפילה חופשית.", choice(["(1)", "(2)", "(3)"], 2), ["graph", "principle"], [
        S(r"מה הגרף אומר", r"בכל נקודה על הקו סכום שתי האנרגיות זהה, ולכן האנרגיה המכנית נשמרת", r"U_G + E_k = 10\,\text{J}"),
        S(r"פוסלים", r"בהיגד הראשון אנרגיית הגובה לא משתנה. בהיגד השני האנרגיה המכנית קטנה בגלל החיכוך", r"\Delta E \ne 0"),
    ], r"(3): רק בנפילה חופשית האנרגיה המכנית נשמרת ואנרגיית הגובה הופכת לקינטית", key=r"היגד 3 מתאים"),
  ],
  concepts=["משפט העבודה והאנרגיה", "עבודת חיכוך", "כוח נטוי וכוח נורמלי", "שימור אנרגיה מכנית"],
  summary=r"תיבה על משטח מחוספס לפי גרף אנרגיה קינטית: מתי פועל כוח נוסף, מה גודלו, העבודה של החיכוך, ואיזה מצב מתאים לגרף של אנרגיה שנשמרת.",
  review="הנחה שלי.\nמה לבדוק: רק לאשר.")
